  if(command==='visualization'){setVisualTrayOpen(true);if(!visualizationBridge.current)throw Error('The visualization tray is still loading.');return visualizationBridge.current.run(input);}
  if(command==='assistant'){
   if(bridgeBusy.current)throw Error('Another browser assistant request is already running.');bridgeBusy.current=true;setBrowserAiBusy(true);const snapshot=JSON.stringify(project);
   try{const response=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project,prompt:input.prompt,selectedRoomId:room?.id,selectedWallCode:view==='walk'?selectedWalkWall?.code:undefined,view,messages:[]})});const result=await response.json() as SparkResult&{error?:string};if(!response.ok)throw Error(result.error||'The assistant request failed.');if(!validProject(result.project)||typeof result.message!=='string')throw Error('Spark returned an invalid project.');if(JSON.stringify(liveProject.current)!==snapshot)throw Error('The project changed while Spark was working. No AI changes applied; retry with the current plan.');let accepted=true;flushSync(()=>{if(JSON.stringify(result.project)!==snapshot)accepted=commit('AI · '+result.message.slice(0,75),p=>replaceProject(p,result.project),'ai');if(result.view&&['plan','orbit','walk'].includes(result.view))setView(result.view);setSelected(null);});if(!accepted)throw Error('The assistant edit was rejected by project validation.');notify(result.message);return {success:true,message:result.message,changes:result.changes,model:result.model,project:result.project};}finally{bridgeBusy.current=false;flushSync(()=>setBrowserAiBusy(false));}
  }
